123	const CRC_TABLE = (() => {
124	  const table = new Uint32Array(256)
125	  for (let n = 0; n < 256; n++) {
126	    let c = n
127	    for (let k = 0; k < 8; k++) {
128	      c = (c & 1) ? (0xedb88320 ^ (c >>> 1)) : (c >>> 1)
129	    }
130	    table[n] = c >>> 0
131	  }
132	  return table
133	})()
