135	function crc32(buf) {
136	  let crc = 0xffffffff
137	  for (let i = 0; i < buf.length; i++) {
138	    crc = CRC_TABLE[(crc ^ buf[i]) & 0xff] ^ (crc >>> 8)
139	  }
140	  return (crc ^ 0xffffffff) >>> 0
141	}
