}
const togglePtasks = () => {
  setShowRuns(false); setViewRun(null)
  setShowPtasks((s) => {
    if (!s) { setPtaskNotice(null); void window.browserAPI.ai.ptaskList().then(setPtasks) }
    return !s
  })

