async function cleanupCard(session, marker) {
  let card = await evaluate(session, cardExpr(marker))
  let openedList = false
  if (!card) {
    // 완료·실패·중단(terminal) 카드는 인라인 진행 목록에서 빠지고 "📌 작업" 전체 목록에만 남는다
